template <class Type> class Table
{
private:
	enum { MAX_SIZE = 16 };
	Type data[MAX_SIZE];
	int size;
public:
	virtual ~Table();
	int Count(void) const { return size; }
	Type &operator[](const int i);
};

class cbVector
{
private:
	unsigned char pData[4];
public:
	inline unsigned char &operator[](int i) { return pData[i]; }
	int DiffMag(const cbVector &Vect) const;
};

class CodeBook
{
private:
	Table<cbVector> VectList;
	Table<int> usageCount;
public:
	virtual ~CodeBook();
	int FindVectorSlow(const cbVector &Vect);
	inline int GetNumCodes(void) const { return VectList.Count(); }
	cbVector &operator[](const int i) { return VectList[i]; }
};

class DXT1Color
{
public:
	DXT1Color() {;}
	DXT1Color(unsigned int c) : Col(c) {;}
	DXT1Color(unsigned char R, unsigned char G, unsigned char B, unsigned char A) : a(A), r(R), g(G), b(B) {;}
	union { struct { unsigned char r, g, b, a; }; unsigned int Col; };
};

class ImageDXTC
{
private:
	static const unsigned int Mask1565;
	static const unsigned int Mask0565;
	static const unsigned short ColorBits4[4];
	static const unsigned short ColorBits3[3];
	int XSize, YSize;
	unsigned char AlphaValue;
	void EmitMultiColorBlock4(unsigned short *pDest, CodeBook &cb, DXT1Color *pSrc);
	inline unsigned short Make565(const DXT1Color & Col) const
	{
		return ((unsigned short)(Col.r >> 3) << 11) | ((unsigned short)(Col.g >> 2) << 5) | ((unsigned short)(Col.b >> 3));
	}
};

void ImageDXTC::EmitMultiColorBlock4(unsigned short *pDest, CodeBook &cb, DXT1Color *pSrc)
{
int x, y, Shift;
unsigned short Index, Col1, Col2;
DXT1Color C, C2;

	C = *((DXT1Color *)&cb[0]);
	C2 = *((DXT1Color *)&cb[3]);

	Col1 = Make565(C);
	Col2 = Make565(C2);

	if(Col1 > Col2)
	{
		pDest[0] = Col1;
		pDest[1] = Col2;
	}
	else if(Col1 < Col2)
	{
		*((DXT1Color *)&cb[0]) = C2;
		*((DXT1Color *)&cb[3]) = C;
		C = *((DXT1Color *)&cb[1]);
		C2 = *((DXT1Color *)&cb[2]);
		*((DXT1Color *)&cb[1]) = C2;
		*((DXT1Color *)&cb[2]) = C;

		pDest[0] = Col2;
		pDest[1] = Col1;
	}
	else
	{
		pDest[0] = Col1;
		pDest[1] = 0;
		pDest[2] = pDest[3] = 0;
		return;
	}

	pDest[2] = 0;
	pDest[3] = 0;
	pDest += 2;

	unsigned char *pcDest = (unsigned char *)pDest;
	for(y=0; y<4; y++)
	{
		Shift = 0;
		for(x=0; x<4; x++)
		{
			Index = ColorBits4[ cb.FindVectorSlow( *((cbVector *)(pSrc+x)) ) ];
			*pcDest |= Index << Shift;
			Shift += 2;
		}
		pSrc += XSize;
		pcDest ++;
	}
}
